// Nullable wrappers for primitive types, used in exported model fields.
type (
	NullableBool    = openapi.NullableBool
	NullableFloat32 = openapi.NullableFloat32
	NullableFloat64 = openapi.NullableFloat64
	NullableInt     = openapi.NullableInt
	NullableInt32   = openapi.NullableInt32
	NullableInt64   = openapi.NullableInt64
	NullableString  = openapi.NullableString
	NullableTime    = openapi.NullableTime
)

// Constructors for the wrappers above. The structs have unexported
// fields, so these are the only way to build one.
func NewNullableBool(val *bool) *NullableBool          { return openapi.NewNullableBool(val) }
func NewNullableFloat32(val *float32) *NullableFloat32 { return openapi.NewNullableFloat32(val) }
func NewNullableFloat64(val *float64) *NullableFloat64 { return openapi.NewNullableFloat64(val) }
func NewNullableInt(val *int) *NullableInt             { return openapi.NewNullableInt(val) }
func NewNullableInt32(val *int32) *NullableInt32       { return openapi.NewNullableInt32(val) }
func NewNullableInt64(val *int64) *NullableInt64       { return openapi.NewNullableInt64(val) }
func NewNullableString(val *string) *NullableString    { return openapi.NewNullableString(val) }
func NewNullableTime(val *time.Time) *NullableTime     { return openapi.NewNullableTime(val) }
